#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
    bool operator<(const Point& p) const {
        return x < p.x || (x == p.x && y < p.y);
    }
};

vector<Point> mackerels, sardines;

int count_m(int x_left, int x_right, int y_left, int y_right) {
    vector<Point> &sorted_m = mackerels;
    int left_idx = 0, right_idx = (int)sorted_m.size();
    while (left_idx < right_idx) {
        int mid = (left_idx + right_idx) / 2;
        if (sorted_m[mid].x < x_left) {
            left_idx = mid + 1;
        } else {
            right_idx = mid;
        }
    }
    int left_idx2 = 0, right_idx2 = (int)sorted_m.size();
    while (left_idx2 < right_idx2) {
        int mid = (left_idx2 + right_idx2) / 2;
        if (sorted_m[mid].x <= x_right) {
            left_idx2 = mid + 1;
        } else {
            right_idx2 = mid;
        }
    }
    int total = 0;
    for (int i = left_idx; i < left_idx2; ++i) {
        if (sorted_m[i].y >= y_left && sorted_m[i].y <= y_right) {
            ++total;
        }
    }
    return total;
}

int count_s(int x_left, int x_right, int y_left, int y_right) {
    vector<Point> &sorted_s = sardines;
    int left_idx = 0, right_idx = (int)sorted_s.size();
    while (left_idx < right_idx) {
        int mid = (left_idx + right_idx) / 2;
        if (sorted_s[mid].x < x_left) {
            left_idx = mid + 1;
        } else {
            right_idx = mid;
        }
    }
    int left_idx2 = 0, right_idx2 = (int)sorted_s.size();
    while (left_idx2 < right_idx2) {
        int mid = (left_idx2 + right_idx2) / 2;
        if (sorted_s[mid].x <= x_right) {
            left_idx2 = mid + 1;
        } else {
            right_idx2 = mid;
        }
    }
    int total = 0;
    for (int i = left_idx; i < left_idx2; ++i) {
        if (sorted_s[i].y >= y_left && sorted_s[i].y <= y_right) {
            ++total;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int N;
    cin >> N;
    mackerels.resize(N);
    sardines.resize(N);
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels[i].x = x; mackerels[i].y = y;
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines[i].x = x; sardines[i].y = y;
    }
    // Sort mackerels by x, then y
    sort(mackerels.begin(), mackerels.end());
    // Sort sardines by x, then y
    sort(sardines.begin(), sardines.end());
    // Compute initial_rect
    int min_x_m = mackerels[0].x;
    int max_x_m = mackerels[N-1].x;
    int min_y_m = mackerels[0].y;
    int max_y_m = mackerels[N-1].y;
    // Now, initial_rect is [min_x_m, max_x_m, min_y_m, max_y_m]
    int best_score = 0;
    int best_x_left = min_x_m;
    int best_x_right = max_x_m;
    int best_y_left = min_y_m;
    int best_y_right = max_y_m;
    // Compute initial score
    int m_count = count_m(min_x_m, max_x_m, min_y_m, max_y_m);
    int s_count = count_s(min_x_m, max_x_m, min_y_m, max_y_m);
    int score = max(0, m_count - s_count + 1);
    if (score > best_score) {
        best_score = score;
        best_x_left = min_x_m;
        best_x_right = max_x_m;
        best_y_left = min_y_m;
        best_y_right = max_y_m;
    }
    // Now check all sardines in initial_rect
    vector<Point> temp_sardines;
    for (int i = 0; i < N; ++i) {
        int x = sardines[i].x;
        int y = sardines[i].y;
        if (x >= min_x_m && x <= max_x_m && y >= min_y_m && y <= max_y_m) {
            temp_sardines.push_back(sardines[i]);
        }
    }
    for (int i = 0; i < temp_sardines.size(); ++i) {
        Point s = temp_sardines[i];
        int sx = s.x;
        int sy = s.y;
        // Generate four new rectangles
        // new_rect1: x_left = min_x_m, x_right = sx -1, y_left = min_y_m, y_right = max_y_m
        int nx_left = min_x_m;
        int nx_right = sx - 1;
        int ny_left = min_y_m;
        int ny_right = max_y_m;
        if (nx_left <= nx_right && ny_left <= ny_right) {
            int m = count_m(nx_left, nx_right, ny_left, ny_right);
            int s_count_curr = count_s(nx_left, nx_right, ny_left, ny_right);
            int current_score = max(0, m - s_count_curr + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x_left = nx_left;
                best_x_right = nx_right;
                best_y_left = ny_left;
                best_y_right = ny_right;
            }
        }
        // new_rect2: x_left = sx + 1, x_right = max_x_m
        nx_left = sx + 1;
        nx_right = max_x_m;
        ny_left = min_y_m;
        ny_right = max_y_m;
        if (nx_left <= nx_right && ny_left <= ny_right) {
            int m = count_m(nx_left, nx_right, ny_left, ny_right);
            int s_count_curr = count_s(nx_left, nx_right, ny_left, ny_right);
            int current_score = max(0, m - s_count_curr + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x_left = nx_left;
                best_x_right = nx_right;
                best_y_left = ny_left;
                best_y_right = ny_right;
            }
        }
        // new_rect3: y_left = min_y_m, y_right = sy - 1, x_left = min_x_m, x_right = max_x_m
        ny_left = min_y_m;
        ny_right = sy - 1;
        nx_left = min_x_m;
        nx_right = max_x_m;
        if (nx_left <= nx_right && ny_left <= ny_right) {
            int m = count_m(nx_left, nx_right, ny_left, ny_right);
            int s_count_curr = count_s(nx_left, nx_right, ny_left, ny_right);
            int current_score = max(0, m - s_count_curr + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x_left = nx_left;
                best_x_right = nx_right;
                best_y_left = ny_left;
                best_y_right = ny_right;
            }
        }
        // new_rect4: y_left = sy + 1, y_right = max_y_m
        ny_left = sy + 1;
        ny_right = max_y_m;
        nx_left = min_x_m;
        nx_right = max_x_m;
        if (nx_left <= nx_right && ny_left <= ny_right) {
            int m = count_m(nx_left, nx_right, ny_left, ny_right);
            int s_count_curr = count_s(nx_left, nx_right, ny_left, ny_right);
            int current_score = max(0, m - s_count_curr + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x_left = nx_left;
                best_x_right = nx_right;
                best_y_left = ny_left;
                best_y_right = ny_right;
            }
        }
    }
    // Now output the best rectangle
    cout << 4 << endl;
    cout << best_x_left << " " << best_y_left << endl;
    cout << best_x_right << " " << best_y_left << endl;
