    int new_x1 = x_l + 1;
    int new_x2 = x_r;
    int new_y1 = y_b;
    int new_y2 = y_t;
    if (new_x1 <= new_x2 && new_y1 <= new_y2) {
        int a = count_mackerels(new_x1, new_x2, new_y1, new_y2);
        if (a > 0) {
            int b = count_sardines(new_x1, new_x2, new_y1, new_y2);
            int diff = a - b;
            if (diff > best_diff) {
                best_diff = diff;
                current_x1 = new_x1;
                current_x2 = new_x2;
                current_y1 = new_y1;
                current_y2 = new_y2;
            }
        }
    }

    // Adjust right
    new_x1 = x_l;
    new_x2 = x_r - 1;
    new_y1 = y_b;
    new_y2 = y_t;
    if (new_x1 <= new_x2 && new_y1 <= new_y2) {
        int a = count_mackerels(new_x1, new_x2, new_y1, new_y2);
        if (a > 0) {
            int b = count_sardines(new_x1, new_x2, new_y1, new_y2);
