                current_x2 = new_x2;
                current_y1 = new_y1;
                current_y2 = new_y2;
            }
        }
    }

    // Adjust bottom
    new_x1 = x_l;
    new_x2 = x_r;
    new_y1 = y_b + 1;
    new_y2 = y_t;
    if (new_x1 <= new_x2 && new_y1 <= new_y2) {
