                    best_b = new_b;
                    best_x1 = best_x1;
                    best_x2 = best_x2;
                    best_y1 = new_y1_bottom;
                    best_y2 = new_y2_bottom;
                    improved = true;
                }
            }
            // Top adjustment
            int new_y1_top = s_y + 1;
            int new_y2_top = best_y2;
            if (new_y1_top <= new_y2_top) {
                int new_a = count_mackerels(best_x1, new_y1_top, best_x2, new_y2_top);
                int new_b = count_sardines(best_x1, new_y1_top, best_x2, new_y2_top);
