#include <iostream>
#include <vector>
#include <tuple>
#include <algorithm>
#include <cmath>
#include <map>

using namespace std;

struct Point {
    int x, y;
    bool is_mackerel;
};

void process_kadane(const vector<Point>& points, vector<int>& contributions, int& start, int& end) {
    int n = contributions.size();
    if (n == 0) {
        start = 0;
        end = 0;
        return;
    }

    int max_sum = contributions[0];
    int current_sum = contributions[0];
    int current_start = 0;
    start = 0;
    end = 0;

    for (int i = 1; i < n; ++i) {
        if (current_sum + contributions[i] > contributions[i]) {
            current_sum += contributions[i];
        } else {
            current_sum = contributions[i];
            current_start = i;
        }

        if (current_sum > max_sum) {
            max_sum = current_sum;
            start = current_start;
            end = i;
        }
    }
}

int main() {
    int N;
    cin >> N;

    vector<Point> all_points;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        Point p = {x, y, (i < N)};
        all_points.push_back(p);
    }

    // Sort all points by x, then y
    sort(all_points.begin(), all_points.end(), [](const Point& a, const Point& b) {
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });

    // Prepare contributions for x-axis
    vector<int> contributions_x;
    for (const auto& p : all_points) {
        contributions_x.push_back(p.is_mackerel ? 1 : -1);
    }

    int start_x, end_x;
    process_kadane(all_points, contributions_x, start_x, end_x);

    // Ensure the subarray has at least two points
    if (start_x == end_x) {
        // Try to extend the subarray by one more point
        // For simplicity, we expand to the next point if possible
        if (end_x + 1 < contributions_x.size()) {
            end_x++;
        } else if (start_x > 0) {
            start_x--;
        } else {
            start_x = 0;
            end_x = 0;
        }
    }

    // Now get x_start and x_end
    int x_start = all_points[start_x].x;
    int x_end = all_points[end_x].x;

    // Repeat for y-axis
    // Prepare a vector sorted by y and then x
    vector<Point> all_points_y;
    for (const auto& p : all_points) {
        all_points_y.push_back(p);
    }
    sort(all_points_y.begin(), all_points_y.end(), [](const Point& a, const Point& b) {
        if (a.y != b.y) return a.y < b.y;
        return a.x < b.x;
    });

    vector<int> contributions_y;
    for (const auto& p : all_points_y) {
        contributions_y.push_back(p.is_mackerel ? 1 : -1);
    }

    int start_y, end_y;
    process_kadane(all_points_y, contributions_y, start_y, end_y);

    if (start_y == end_y) {
        if (end_y + 1 < contributions_y.size()) {
            end_y++;
        } else if (start_y > 0) {
            start_y--;
        } else {
            start_y = 0;
            end_y = 0;
        }
    }

    // Now get y_start and y_end
    int y_start = all_points_y[start_y].y;
    int y_end = all_points_y[end_y].y;

    // Ensure the rectangle has positive width and height
    // Check if x_start < x_end and y_start < y_end
    if (x_start >= x_end) {
        x_start = all_points[start_x].x - 1;
        x_end = all_points[start_x].x + 1;
    }
    if (y_start >= y_end) {
        y_start = all_points_y[start_y].y - 1;
        y_end = all_points_y[start_y].y + 1;
    }

    // Ensure the rectangle is valid
    if (x_start >= x_end || y_start >= y_end) {
        // Default to a small rectangle
        x_start = 0;
        x_end = 1;
        y_start = 0;
        y_end = 1;
    }

    // Output the polygon
    cout << 4 << endl;
    cout << x_start << " " << y_start << endl;
    cout << x_end << " " << y_start << endl;
    cout << x_end << " " << y_end << endl;
