struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for(int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute original MBR for mackerels
    int x_min_m = INT_MAX;
    int x_max_m = INT_MIN;
    int y_min_m = INT_MAX;
    int y_max_m = INT_MIN;

    for (auto p : mackerels) {
        x_min_m = min(x_min_m, p.x);
        x_max_m = max(x_max_m, p.x);
        y_min_m = min(y_min_m, p.y);
        y_max_m = max(y_max_m, p.y);
    }

    // Find all sardines inside the MBR
    vector<Point> sardines_in_mbr;
    for (auto p : sardines) {
        if (p.x >= x_min_m && p.x <= x_max_m && p.y >= y_min_m && p.y <= y_max_m) {
            sardines_in_mbr.push_back(p);
        }
    }

    auto compute_counts = [&](int x1, int y1, int x2, int y2) {
        int a = 0;
        for (auto p : mackerels) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                a++;
            }
        }
        int b = 0;
        for (auto p : sardines) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                b++;
            }
        }
        return make_pair(a, b);
    };

    auto is_valid = [&](int x1, int y1, int x2, int y2) {
        return x1 <= x2 && y1 <= y2;
    };

    int best_score = 0;
    int best_a = 0;
    int best_b = 0;
    int best_x1 = x_min_m;
    int best_x2 = x_max_m;
    int best_y1 = y_min_m;
    int best_y2 = y_max_m;

    // Compute original a and b
    int original_a = N;
    int original_b = 0;
    for (auto p : sardines) {
        if (p.x >= x_min_m && p.x <= x_max_m && p.y >= y_min_m && p.y <= y_max_m) {
            original_b++;
        }
    }
    int original_score = max(0, original_a - original_b + 1);
    best_score = original_score;
    best_a = original_a;
    best_b = original_b;
    best_x1 = x_min_m;
    best_x2 = x_max_m;
    best_y1 = y_min_m;
    best_y2 = y_max_m;

    // Process each sardine in sardines_in_mbr
    for (auto s : sardines_in_mbr) {
        int sx = s.x;
        int sy = s.y;

        // Candidate 1: move right boundary to sx - 1
        int new_x1 = x_min_m;
        int new_x2 = sx - 1;
        int new_y1 = y_min_m;
        int new_y2 = y_max_m;
        if (is_valid(new_x1, new_y1, new_x2, new_y2)) {
            auto [a, b] = compute_counts(new_x1, new_y1, new_x2, new_y2);
            int score = max(0, a - b + 1);
            if (score > best_score) {
                best_score = score;
                best_a = a;
                best_b = b;
                best_x1 = new_x1;
                best_x2 = new_x2;
                best_y1 = new_y1;
                best_y2 = new_y2;
            }
        }

        // Candidate 2: move left boundary to sx + 1
        new_x1 = sx + 1;
        new_x2 = x_max_m;
        new_y1 = y_min_m;
        new_y2 = y_max_m;
        if (is_valid(new_x1, new_y1, new_x2, new_y2)) {
            auto [a, b] = compute_counts(new_x1, new_y1, new_x2, new_y2);
            int score = max(0, a - b + 1);
            if (score > best_score) {
                best_score = score;
                best_a = a;
                best_b = b;
                best_x1 = new_x1;
                best_x2 = new_x2;
                best_y1 = new_y1;
                best_y2 = new_y2;
            }
        }

        // Candidate 3: move top boundary to sy - 1
        new_y1 = y_min_m;
        new_y2 = sy - 1;
        new_x1 = x_min_m;
        new_x2 = x_max_m;
        if (is_valid(new_x1, new_y1, new_x2, new_y2)) {
            auto [a, b] = compute_counts(new_x1, new_y1, new_x2, new_y2);
            int score = max(0, a - b + 1);
            if (score > best_score) {
                best_score = score;
                best_a = a;
                best_b = b;
                best_x1 = new_x1;
                best_x2 = new_x2;
                best_y1 = new_y1;
                best_y2 = new_y2;
            }
        }

        // Candidate 4: move bottom boundary to sy + 1
        new_y1 = sy + 1;
        new_y2 = y_max_m;
        new_x1 = x_min_m;
        new_x2 = x_max_m;
        if (is_valid(new_x1, new_y1, new_x2, new_y2)) {
            auto [a, b] = compute_counts(new_x1, new_y1, new_x2, new_y2);
            int score = max(0, a - b + 1);
            if (score > best_score) {
                best_score = score;
                best_a = a;
                best_b = b;
                best_x1 = new_x1;
                best_x2 = new_x2;
                best_y1 = new_y1;
                best_y2 = new_y2;
            }
        }
    }

    // Check if the best rectangle has valid area
    if (best_x1 == best_x2 || best_y1 == best_y2) {
        // Adjust to make it valid
        if (best_x1 == best_x2) {
            if (best_x2 < 100000) {
                best_x2++;
            } else {
                if (best_x1 > 0) {
                    best_x1--;
                } else {
                    best_x1 = 0;
                    best_x2 = 1;
                }
            }
        }
        if (best_y1 == best_y2) {
            if (best_y2 < 100000) {
                best_y2++;
            } else {
                if (best_y1 > 0) {
                    best_y1--;
                } else {
                    best_y1 = 0;
                    best_y2 = 1;
                }
            }
        }
    }

    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
#include <utility>
#include <cmath>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort mackerels and sardines by x, then y
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });

    // Function to count mackerels in [x1, x2] x [y1, y2]
    auto count_mackerels = [&](int x1, int y1, int x2, int y2) {
        int cnt = 0;
        auto left = lower_bound(mackerels.begin(), mackerels.end(), make_pair(x1, 0),
                                [](const pair<int, int>& a, const pair<int, int>& b) {
                                    return a.first < b.first;
                                });
        auto right = upper_bound(mackerels.begin(), mackerels.end(), make_pair(x2, INT_MAX),
                                 [](const pair<int, int>& a, const pair<int, int>& b) {
                                     return a.first < b.first;
                                 });
        for (auto it = left; it != right; ++it) {
            if (it->second >= y1 && it->second <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    // Function to count sardines in [x1, x2] x [y1, y2]
    auto count_sardines = [&](int x1, int y1, int x2, int y2) {
        int cnt = 0;
        auto left = lower_bound(sardines.begin(), sardines.end(), make_pair(x1, 0),
                                [](const pair<int, int>& a, const pair<int, int>& b) {
                                    return a.first < b.first;
                                });
        auto right = upper_bound(sardines.begin(), sardines.end(), make_pair(x2, INT_MAX),
                                 [](const pair<int, int>& a, const pair<int, int>& b) {
                                     return a.first < b.first;
                                 });
        for (auto it = left; it != right; ++it) {
            if (it->second >= y1 && it->second <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    // Initialize with bounding box of mackerels
    int min_x = INT_MAX, max_x = INT_MIN, min_y = INT_MAX, max_y = INT_MIN;
    for (auto [x, y] : mackerels) {
        min_x = min(min_x, x);
        max_x = max(max_x, x);
        min_y = min(min_y, y);
        max_y = max(max_y, y);
    }

    int best_x1 = min_x, best_x2 = max_x, best_y1 = min_y, best_y2 = max_y;
    int best_a = count_mackerels(best_x1, best_y1, best_x2, best_y2);
    int best_b = count_sardines(best_x1, best_y1, best_x2, best_y2);

    bool improved;
    do {
        improved = false;
        // Find all sardines inside current rectangle
        vector<pair<int, int>> sardines_in_rect;
        for (auto [x, y] : sardines) {
            if (x >= best_x1 && x <= best_x2 && y >= best_y1 && y <= best_y2) {
                sardines_in_rect.push_back({x, y});
            }
        }

        if (sardines_in_rect.empty()) {
            break;
        }

        int best_gain = -1;
        int new_x1 = best_x1, new_x2 = best_x2, new_y1 = best_y1, new_y2 = best_y2;
        int gain = 0;

        for (auto s : sardines_in_rect) {
            int s_x = s.first;
            int s_y = s.second;

            // Try adjusting x1 (left)
            int temp_x1 = s_x - 1;
            if (temp_x1 < best_x2) {
                int a = count_mackerels(temp_x1, best_y1, best_x2, best_y2);
                int b = count_sardines(temp_x1, best_y1, best_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = temp_x1;
                    new_x2 = best_x2;
                    new_y1 = best_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting x2 (right)
            int temp_x2 = s_x + 1;
            if (temp_x2 > best_x1) {
                int a = count_mackerels(best_x1, best_y1, temp_x2, best_y2);
                int b = count_sardines(best_x1, best_y1, temp_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = temp_x2;
                    new_y1 = best_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting y1 (bottom)
            int temp_y1 = s_y - 1;
            if (temp_y1 < best_y2) {
                int a = count_mackerels(best_x1, temp_y1, best_x2, best_y2);
                int b = count_sardines(best_x1, temp_y1, best_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = best_x2;
                    new_y1 = temp_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting y2 (top)
            int temp_y2 = s_y + 1;
            if (temp_y2 > best_y1) {
                int a = count_mackerels(best_x1, best_y1, best_x2, temp_y2);
                int b = count_sardines(best_x1, best_y1, best_x2, temp_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = best_x2;
                    new_y1 = best_y1;
                    new_y2 = temp_y2;
                }
            }
        }

        if (best_gain > 0) {
            best_a = count_mackerels(new_x1, new_y1, new_x2, new_y2);
            best_b = count_sardines(new_x1, new_y1, new_x2, new_y2);
            best_x1 = new_x1;
            best_x2 = new_x2;
            best_y1 = new_y1;
            best_y2 = new_y2;
            improved = true;
        }
    } while (improved);

    cout << 4 << endl;
