    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort mackerels and sardines by x, then y
    sort(mackerels.begin(), mackerels.end());
    sort(sardines.begin(), sardines.end());

    // Compute initial rectangle (min and max for mackerels)
    int x_min1 = INT_MAX;
    int x_max1 = INT_MIN;
    int y_min1 = INT_MAX;
    int y_max1 = INT_MIN;

    for (const auto& p : mackerels) {
        x_min1 = min(x_min1, p.x);
        x_max1 = max(x_max1, p.x);
        y_min1 = min(y_min1, p.y);
        y_max1 = max(y_max1, p.y);
    }

    // Helper functions to count enclosed points
    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        int low = 0, high = mackerels.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (mackerels[mid].x < x_min) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        int start = low;
        low = 0, high = mackerels.size();
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (mackerels[mid].x > x_max) {
                high = mid - 1;
            } else {
                low = mid;
            }
        }
        int end = low;
        for (int i = start; i <= end; ++i) {
            if (mackerels[i].y >= y_min && mackerels[i].y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        int low = 0, high = sardines.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (sardines[mid].x < x_min) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        int start = low;
        low = 0, high = sardines.size();
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (sardines[mid].x > x_max) {
                high = mid - 1;
            } else {
                low = mid;
            }
        }
        int end = low;
        for (int i = start; i <= end; ++i) {
            if (sardines[i].y >= y_min && sardines[i].y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    // Initial score calculation
    int b_initial = count_sardines(x_min1, x_max1, y_min1, y_max1);
    int max_val = (N - b_initial + 1);
    if (max_val < 0) max_val = 0;
    int best_x_min = x_min1;
    int best_x_max = x_max1;
    int best_y_min = y_min1;
    int best_y_max = y_max1;

    // Try adjusting for each sardine to exclude them
    for (const auto& s : sardines) {
        int xs = s.x;
        int ys = s.y;
        bool inside = (xs >= x_min1 && xs <= x_max1 && ys >= y_min1 && ys <= y_max1);

        if (inside) {
            // Adjust x_max
            int new_xmax = xs - 1;
            if (new_xmax >= x_min1) {
                int a = count_mackerels(x_min1, new_xmax, y_min1, y_max1);
                int b = count_sardines(x_min1, new_xmax, y_min1, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = new_xmax;
                    best_y_min = y_min1;
                    best_y_max = y_max1;
                }
            }

            // Adjust x_min
            int new_xmin = xs + 1;
            if (new_xmin <= x_max1) {
                int a = count_mackerels(new_xmin, x_max1, y_min1, y_max1);
                int b = count_sardines(new_xmin, x_max1, y_min1, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = new_xmin;
                    best_x_max = x_max1;
                    best_y_min = y_min1;
                    best_y_max = y_max1;
                }
            }

            // Adjust y_max
            int new_ymax = ys - 1;
            if (new_ymax >= y_min1) {
                int a = count_mackerels(x_min1, x_max1, y_min1, new_ymax);
                int b = count_sardines(x_min1, x_max1, y_min1, new_ymax);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = x_max1;
                    best_y_min = y_min1;
                    best_y_max = new_ymax;
                }
            }

            // Adjust y_min
            int new_ymin = ys + 1;
            if (new_ymin <= y_max1) {
                int a = count_mackerels(x_min1, x_max1, new_ymin, y_max1);
                int b = count_sardines(x_min1, x_max1, new_ymin, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = x_max1;
                    best_y_min = new_ymin;
                    best_y_max = y_max1;
                }
            }
        }
    }

    // Output the best rectangle found
