    // Add the initial rectangle as a candidate
    Rect initial_rect;
    initial_rect.xmin = x_min_m;
    initial_rect.ymin = y_min_m;
    initial_rect.xmax = x_max_m;
    initial_rect.ymax = y_max_m;
