            if (new_ymax3 >= current_best.ymin) {
                Rect r;
                r.xmin = current_best.xmin;
                r.ymin = current_best.ymin;
                r.xmax = current_best.xmax;
                r.ymax = new_ymax3;
                new_candidates.push_back(r);
            }
            // 4. adjust y_min to sy + 1
            int new_ymin4 = sy + 1;
            if (new_ymin4 <= current_best.ymax) {
                Rect r;
                r.xmin = current_best.xmin;
                r.ymin = new_ymin4;
                r.xmax = current_best.xmax;
                r.ymax = current_best.ymax;
                new_candidates.push_back(r);
            }
        }
    }

    // Add new candidates to the candidates
    for (auto r : new_candidates) {
        candidates.push_back(r);
    }

    // Re-evaluate all candidates
    for (auto r : candidates) {
        int xmin = r.xmin;
        int ymin = r.ymin;
        int xmax = r.xmax;
