                r.xmin = x_min_m;
                r.ymin = new_ymin4;
                r.xmax = x_max_m;
                r.ymax = new_ymax4;
                candidates.push_back(r);
            }
            // 5. x-left and y-bottom
            int new_xmin5 = sx + 1;
            int new_xmax5 = x_max_m;
            int new_ymin5 = sy + 1;
            int new_ymax5 = y_max_m;
            if (new_xmax5 >= new_xmin5 && new_ymax5 >= new_ymin5) {
                Rect r;
                r.xmin = new_xmin5;
                r.ymin = new_ymin5;
                r.xmax = new_xmax5;
                r.ymax = new_ymax5;
                candidates.push_back(r);
            }
            // 6. x-left and y-top
            int new_xmin6 = sx + 1;
            int new_xmax6 = x_max_m;
            int new_ymin6 = y_min_m;
            int new_ymax6 = sy - 1;
            if (new_xmax6 >= new_xmin6 && new_ymax6 >= new_ymin6) {
                Rect r;
                r.xmin = new_xmin6;
                r.ymin = new_ymin6;
                r.xmax = new_xmax6;
                r.ymax = new_ymax6;
                candidates.push_back(r);
