                r.ymin = new_ymin8;
                r.xmax = new_xmax8;
                r.ymax = new_ymax8;
                candidates.push_back(r);
            }
        }
    }

    // Now, for each candidate rectangle, compute the value a - b
    int best_diff = -1;
    Rect best_rect;
    best_rect.xmin = x_min_m;
    best_rect.ymin = y_min_m;
    best_rect.xmax = x_max_m;
    best_rect.ymax = y_max_m;

