        int b = 0;
        for (auto [sx, sy] : sardines) {
            if (sx >= xmin && sx <= xmax && sy >= ymin && sy <= ymax) {
                b++;
            }
        }

        int diff = a - b;
        if (diff > best_diff) {
            best_diff = diff;
            best_rect.xmin = xmin;
            best_rect.ymin = ymin;
            best_rect.xmax = xmax;
            best_rect.ymax = ymax;
        }
    }

