    auto count_mackerels = [&](int x1, int x2, int y1, int y2) {
        int count = 0;
        for (const auto& m : mackerels) {
            if (m.first >= x1 && m.first <= x2 && m.second >= y1 && m.second <= y2) {
                count++;
            }
        }
        return count;
    };

    // Function to count sardines in rectangle
    auto count_sardines = [&](int x1, int x2, int y1, int y2) {
        int count = 0;
        for (const auto& s : sardines) {
            if (s.first >= x1 && s.first <= x2 && s.second >= y1 && s.second <= y2) {
                count++;
            }
        }
        return count;
    };

    int best_score = 0;
    int best_x1 = x_min, best_x2 = x_max, best_y1 = y_min, best_y2 = y_max;
