                    current_x1 = new_x1;
                    improved = true;
                }
            }

            // Try adjusting x2
            int new_x2 = s.first - 1;
            if (new_x2 >= current_x1) {
                int a = count_mackerels(current_x1, new_x2, current_y1, current_y2);
                int b = count_sardines(current_x1, new_x2, current_y1, current_y2);
                if (a - b > best_score) {
                    best_score = a - b;
                    current_x2 = new_x2;
                    improved = true;
                }
            }

            // Try adjusting y1
            int new_y1 = s.second + 1;
            if (new_y1 <= current_y2) {
