    vector<pair<int, int>> sardines_sorted_y;
    for (auto s : sardines_in_initial) {
        sardines_sorted_y.push_back({s.second, s.first});
    }
    sort(sardines_sorted_y.begin(), sardines_sorted_y.end());
    vector<int> sorted_y_s;
    for (auto p : sardines_sorted_y) {
        sorted_y_s.push_back(p.first);
    }

    // Initial count of mackerels and sardines_in_initial
    int initial_m = N;
    int initial_s = sardines_in_initial.size();

    int best_score = max(0, initial_m - initial_s + 1);
    int best_min_x = min_x, best_max_x = max_x;
    int best_min_y = min_y, best_max_y = max_y;

    // Now, for each sardine in sardines_in_initial
    for (auto s : sardines_in_initial) {
        // Case 1: shrink right edge to s.x - 1
        int new_min_x = min_x;
        int new_max_x = s.first - 1;
        if (new_max_x >= new_min_x) {
            // count mackerels in [new_min_x, new_max_x]
            auto it_low = lower_bound(sorted_x_m.begin(), sorted_x_m.end(), new_min_x);
            auto it_high = upper_bound(sorted_x_m.begin(), sorted_x_m.end(), new_max_x);
            int cnt_m = it_high - it_low;

            // count sardines in x range [new_min_x, new_max_x]
            auto it_low_s = lower_bound(sorted_x_s.begin(), sorted_x_s.end(), new_min_x);
            auto it_high_s = upper_bound(sorted_x_s.begin(), sorted_x_s.end(), new_max_x);
            int cnt_s = it_high_s - it_low_s;

            int score = max(0, cnt_m - cnt_s + 1);
            if (score > best_score) {
                best_score = score;
                best_min_x = new_min_x;
                best_max_x = new_max_x;
                best_min_y = min_y;
                best_max_y = max_y;
            }
        }

        // Case 2: shrink left edge to s.x + 1
        int new_min_x2 = s.first + 1;
        int new_max_x2 = max_x;
        if (new_min_x2 <= new_max_x2) {
            auto it_low = lower_bound(sorted_x_m.begin(), sorted_x_m.end(), new_min_x2);
            auto it_high = upper_bound(sorted_x_m.begin(), sorted_x_m.end(), new_max_x2);
            int cnt_m = it_high - it_low;

            auto it_low_s = lower_bound(sorted_x_s.begin(), sorted_x_s.end(), new_min_x2);
            auto it_high_s = upper_bound(sorted_x_s.begin(), sorted_x_s.end(), new_max_x2);
            int cnt_s = it_high_s - it_low_s;

            int score = max(0, cnt_m - cnt_s + 1);
            if (score > best_score) {
                best_score = score;
                best_min_x = new_min_x2;
                best_max_x = new_max_x2;
                best_min_y = min_y;
                best_max_y = max_y;
            }
        }

        // Case 3: shrink top edge to s.y - 1
        int new_min_y3 = min_y;
        int new_max_y3 = s.second - 1;
        if (new_max_y3 >= new_min_y3) {
            auto it_low_m = lower_bound(sorted_y_m.begin(), sorted_y_m.end(), new_min_y3);
            auto it_high_m = upper_bound(sorted_y_m.begin(), sorted_y_m.end(), new_max_y3);
            int cnt_m = it_high_m - it_low_m;

            auto it_low_s = lower_bound(sorted_y_s.begin(), sorted_y_s.end(), new_min_y3);
            auto it_high_s = upper_bound(sorted_y_s.begin(), sorted_y_s.end(), new_max_y3);
            int cnt_s = it_high_s - it_low_s;

            int score = max(0, cnt_m - cnt_s + 1);
            if (score > best_score) {
                best_score = score;
                best_min_x = min_x;
                best_max_x = max_x;
                best_min_y = new_min_y3;
                best_max_y = new_max_y3;
            }
        }

        // Case 4: shrink bottom edge to s.y + 1
        int new_min_y4 = s.second + 1;
        int new_max_y4 = max_y;
        if (new_min_y4 <= new_max_y4) {
            auto it_low_m = lower_bound(sorted_y_m.begin(), sorted_y_m.end(), new_min_y4);
            auto it_high_m = upper_bound(sorted_y_m.begin(), sorted_y_m.end(), new_max_y4);
            int cnt_m = it_high_m - it_low_m;

            auto it_low_s = lower_bound(sorted_y_s.begin(), sorted_y_s.end(), new_min_y4);
            auto it_high_s = upper_bound(sorted_y_s.begin(), sorted_y_s.end(), new_max_y4);
            int cnt_s = it_high_s - it_low_s;

            int score = max(0, cnt_m - cnt_s + 1);
            if (score > best_score) {
                best_score = score;
                best_min_x = min_x;
                best_max_x = max_x;
                best_min_y = new_min_y4;
                best_max_y = new_max_y4;
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_min_x << ' ' << best_min_y << endl;
    cout << best_max_x << ' ' << best_min_y << endl;
    cout << best_max_x << ' ' << best_max_y << endl;
    cout << best_min_x << ' ' << best_max_y << endl;

    return 0;
}
